import{_ as t,o,c as r,ag as e}from"./chunks/framework.CAXxHpAX.js";const p=JSON.parse('{"title":"圆融中和","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-圆融中和.md","filePath":"10-核心模型/model-圆融中和.md","lastUpdated":1778031108000}'),l={name:"10-核心模型/model-圆融中和.md"};function n(i,a,s,h,u,d){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="圆融中和" tabindex="-1">圆融中和 <a class="header-anchor" href="#圆融中和" aria-label="Permalink to &quot;圆融中和&quot;">​</a></h1><blockquote><p>了空居士智慧体系的处世智慧。 凡夫开口闭口都是边见，真正的智慧是中道。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>圆融中和</strong> 是了空居士教导中处世智慧的精髓。它反对一切&quot;边见&quot;（极端化、片面化的判断），倡导不偏不倚、灵活应变的处世态度。<strong>不是折中主义，而是因地制宜的智慧。</strong></p><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="_1-守中" tabindex="-1">1. 守中 <a class="header-anchor" href="#_1-守中" aria-label="Permalink to &quot;1. 守中&quot;">​</a></h3><p><strong>原文</strong>：多言数穷，不如守中。&quot;中&quot;就是最客观，看准最佳时机。</p><p><strong>解读</strong>：说很多话、想很多办法，不如看准时机，以最佳的方式去做。守中不是不动，而是不盲动、不妄动。</p><h3 id="_2-离边见" tabindex="-1">2. 离边见 <a class="header-anchor" href="#_2-离边见" aria-label="Permalink to &quot;2. 离边见&quot;">​</a></h3><p><strong>原文</strong>：凡夫开口闭口都是边见。</p><p><strong>解读</strong>：&quot;边见&quot;就是非此即彼的极端化思维。了空居士常说&quot;好不好&quot;这种提问本身就是边见——飞机好不好？好。但大街小巷几公里，飞机怎么办？所以没有什么绝对的好不好，要看具体情况。</p><h3 id="_3-和光同尘" tabindex="-1">3. 和光同尘 <a class="header-anchor" href="#_3-和光同尘" aria-label="Permalink to &quot;3. 和光同尘&quot;">​</a></h3><p><strong>原文</strong>：挫其锐，解其纷，和其光，同其尘。</p><p><strong>解读</strong>：收敛锋芒，不张扬，在光明之处能待，在凡俗之处也能待。不是随波逐流，而是包容一切。</p><h3 id="_4-纯一直心" tabindex="-1">4. 纯一直心 <a class="header-anchor" href="#_4-纯一直心" aria-label="Permalink to &quot;4. 纯一直心&quot;">​</a></h3><p><strong>原文</strong>：坦坦荡荡，纯一直心地去做。</p><p><strong>解读</strong>：最简单的处世方式——不绕弯子，不耍心机，坦坦荡荡。但纯直不等于魯莽，是内心澄澈的外在流露。</p><h3 id="_5-平等心-均等" tabindex="-1">5. 平等心≠均等 <a class="header-anchor" href="#_5-平等心-均等" aria-label="Permalink to &quot;5. 平等心≠均等&quot;">​</a></h3><p><strong>原文</strong>：平等心是物有所值，不是所有东西都一样。</p><p><strong>解读</strong>：很多人把平等误解为&quot;一刀切&quot;。了空居士用黄金和废铁比喻——黄金贵是因为稀缺难求，废铁便宜是因为丰富易得，这才是真正的平等。平等是按事物的本来面目去对待，不是强求一致。</p><h3 id="_6-柔弱胜刚强" tabindex="-1">6. 柔弱胜刚强 <a class="header-anchor" href="#_6-柔弱胜刚强" aria-label="Permalink to &quot;6. 柔弱胜刚强&quot;">​</a></h3><p><strong>原文</strong>：天下之至柔，驰骋天下之至坚。</p><p><strong>解读</strong>：潜移默化的力量大于硬碰硬的对抗。水是最柔的，但滴水可以穿石。</p><h3 id="_7-非法非非法" tabindex="-1">7. 非法非非法 <a class="header-anchor" href="#_7-非法非非法" aria-label="Permalink to &quot;7. 非法非非法&quot;">​</a></h3><p><strong>原文</strong>：如来所说法，皆不可取，不可说，非法，非非法。</p><p><strong>解读</strong>：佛祖说的法，不是固定方法（非法），也不是没有方法（非非法）。如同钥匙开锁——这把钥匙能开这个锁，但不一定能开其他锁。方法对特定问题是有效的，但不是放之四海皆准的。所以既不能执着（非法），也不能全盘否定（非非法）。</p><h3 id="_8-整体观" tabindex="-1">8. 整体观 <a class="header-anchor" href="#_8-整体观" aria-label="Permalink to &quot;8. 整体观&quot;">​</a></h3><p><strong>原文</strong>：在任何一个时空点上，还是有是非对错的标准的——这就是整体观。</p><p><strong>解读</strong>：判断事情对错，不能只站在自己的立场，要从整体来衡量。&quot;归宗斩蛇&quot;——从蛇的角度看是杀生，从人类安全看是除害，从三世因果看是帮蛇少造罪业。整体观就是跳出局部，看全局。</p><h3 id="_9-是非对错的相对性" tabindex="-1">9. 是非对错的相对性 <a class="header-anchor" href="#_9-是非对错的相对性" aria-label="Permalink to &quot;9. 是非对错的相对性&quot;">​</a></h3><p><strong>原文</strong>：没有绝对的放之四海皆准的是非对错标准，但是在具体情境下还是有是非对错的。</p><p><strong>解读</strong>：一切标准都是相对的，但在特定时间地点还是有标准的。不能说&quot;一切法皆是佛法&quot;就没有是非了。日本侵华，站在他们立场说&quot;帮助落后民族&quot;，站不住——&quot;己所不欲，勿施于人&quot;就是底线的整体观。</p><h3 id="_10-智慧布施" tabindex="-1">10. 智慧布施 <a class="header-anchor" href="#_10-智慧布施" aria-label="Permalink to &quot;10. 智慧布施&quot;">​</a></h3><p><strong>原文</strong>：该怎么做最完美就尽量那么做——布施也要有智慧。</p><p><strong>解读</strong>：看到歹徒行凶，不是冲上去挨刀就叫&quot;以身布施&quot;。有智慧的人会观察，能报警就报警，能智取就智取。慈悲需要智慧引导，不是盲目牺牲。</p><h3 id="_11-无断无灭" tabindex="-1">11. 无断无灭 <a class="header-anchor" href="#_11-无断无灭" aria-label="Permalink to &quot;11. 无断无灭&quot;">​</a></h3><p><strong>原文</strong>：发阿耨多罗三藐三菩提心者，于法不说断灭相。</p><p><strong>解读</strong>：说空不能落入断灭见。不能说&quot;一切皆空&quot;就什么都不做了。修行人应&quot;于有离有，于空离空&quot;——不着有也不落空，这才是中道。</p><h3 id="_12-整体观定善恶" tabindex="-1">12. 整体观定善恶 <a class="header-anchor" href="#_12-整体观定善恶" aria-label="Permalink to &quot;12. 整体观定善恶&quot;">​</a></h3><p><strong>原文</strong>：善恶有标准——以整体观来定，对大众整体有益就是善，有害就是恶。</p><p><strong>解读</strong>：有修行人说&quot;善恶没有标准&quot;，这是错的。善恶当然有标准——武松打虎是为民除害，现代人打虎是偷猎，同样行为不同结果。标准就是整体观：对大众整体有利的就是善。自利利他是善，害己害人是恶。</p><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><p><strong>思考问题时</strong>：</p><ul><li>不急于下结论，问自己&quot;有没有第三种可能？&quot;</li><li>避免&quot;好与坏&quot;&quot;对与错&quot;&quot;应该与不应该&quot;的二元判断</li><li>看到事情的两面性，找到中间的平衡点</li></ul><p><strong>为人处世时</strong>：</p><ul><li>不锋芒毕露，也不软弱退缩</li><li>对长辈有恭敬但不过度卑微，对后辈有爱护但不过度纵容</li><li>包容不同意见，但不失自己的立场</li></ul><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 对境不住是圆融中和的心态基础</li><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 不执着才能圆融</li><li><a href="/10-核心模型/model-历境炼心">历境炼心</a> — 圆融中和是炼心的结果</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第1分（法会由分）</li><li>金刚经第4分（妙行无住分）</li><li>金刚经第5分（如理实见分）</li><li>金刚经第7分（无得无说分）</li><li>金刚经第8分（依法出生分）</li><li>金刚经第11分（无为福胜分）</li><li>道德经讲解</li></ul><blockquote><p>来源：<a href="/道德经讲解">道德经讲解</a>、<a href="/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a> 蒸馏日期：2026-05-05（第一版）2026-05-05（第二版，新增3个原子）</p></blockquote>',55)])])}const g=t(l,[["render",n]]);export{p as __pageData,g as default};
